    PRIMARY KEY (id),
    CONSTRAINT uk_webserver_domain_verification_uuid UNIQUE (uuid),
    CONSTRAINT fk_webserver_domain_verification_domain FOREIGN KEY (tenant_id, domain_id)
        REFERENCES webserver_domain(tenant_id, id),
    CONSTRAINT chk_webserver_domain_verification_method CHECK (method IN ('DNS_TXT', 'DNS_CNAME', 'HTTP_FILE')),
    CONSTRAINT chk_webserver_domain_verification_status CHECK (status IN ('PENDING', 'CHECKING', 'VERIFIED', 'FAILED', 'EXPIRED')),
    CONSTRAINT chk_webserver_domain_verification_hash CHECK (
        proof_sha256 ~ '^[0-9a-f]{64}$'
        AND (observed_sha256 IS NULL OR observed_sha256 ~ '^[0-9a-f]{64}$')
