CREATE UNIQUE INDEX IF NOT EXISTS uk_webserver_domain_verification_active
    ON webserver_domain_verification (domain_id)
    WHERE status IN ('PENDING', 'CHECKING');

CREATE INDEX IF NOT EXISTS idx_webserver_domain_verification_due
    ON webserver_domain_verification (status, next_attempt_at, expires_at, id)
    WHERE status IN ('PENDING', 'CHECKING');

-- The last synced snapshot of one Zone's DNS resolution records, read from the
-- provider through the Zone's cloud account (`webserver_root_domain` 0023).
-- One sync run replaces the Zone's whole snapshot in one transaction, so the
-- table always answers with what the provider answered at `synced_at` -- never
-- a merge of two runs. `domain_id` is the subdomain the record resolves (matched
-- at sync time); NULL is the state of a record whose owner matches no
-- registered hostname, which the resolution page still shows at Zone scope.
CREATE TABLE IF NOT EXISTS webserver_domain_dns_record (
    id              BIGINT        NOT NULL,
    uuid            VARCHAR(64)   NOT NULL,
    tenant_id       BIGINT        NOT NULL DEFAULT 0,
    organization_id BIGINT        NOT NULL DEFAULT 0,
    root_domain_id  BIGINT        NOT NULL,
    domain_id       BIGINT,
    record_name     VARCHAR(253)  NOT NULL,
    record_type     VARCHAR(16)   NOT NULL,
    record_value    VARCHAR(1024) NOT NULL,
    ttl_seconds     INTEGER,
    priority        INTEGER,
    record_line     VARCHAR(64),
    dns_provider    VARCHAR(32)   NOT NULL,
    cloud_account_id VARCHAR(128) NOT NULL,
    provider_record_ref VARCHAR(128),
    record_status   VARCHAR(8)    NOT NULL DEFAULT 'ENABLED',
    synced_at       TIMESTAMPTZ   NOT NULL,
    created_at      TIMESTAMPTZ   NOT NULL,
    updated_at      TIMESTAMPTZ   NOT NULL,
    version         BIGINT        NOT NULL DEFAULT 0,
    deleted_at      TIMESTAMPTZ,
    PRIMARY KEY (id),
    CONSTRAINT uk_webserver_domain_dns_record_uuid UNIQUE (uuid),
    CONSTRAINT uk_webserver_domain_dns_record_tenant_id UNIQUE (tenant_id, id),
    CONSTRAINT fk_webserver_domain_dns_record_root_domain FOREIGN KEY (tenant_id, root_domain_id)
        REFERENCES webserver_root_domain(tenant_id, id),
    CONSTRAINT fk_webserver_domain_dns_record_domain FOREIGN KEY (tenant_id, domain_id)
        REFERENCES webserver_domain(tenant_id, id),
    CONSTRAINT chk_webserver_domain_dns_record_owner CHECK (record_name <> ''),
    CONSTRAINT chk_webserver_domain_dns_record_status CHECK (
        record_status IN ('ENABLED', 'DISABLED')
    ),
    CONSTRAINT chk_webserver_domain_dns_record_cloud_account CHECK (
        cloud_account_id ~ '^[A-Za-z0-9][A-Za-z0-9_.:-]{1,127}$'
    )
);

COMMENT ON TABLE webserver_domain_dns_record IS 'Synced snapshot of one root-domain Zone DNS resolution records';
COMMENT ON COLUMN webserver_domain_dns_record.domain_id IS 'Subdomain the record resolves; NULL when its owner matches no registered hostname';
COMMENT ON COLUMN webserver_domain_dns_record.record_status IS 'Provider-side resolution state at snapshot time: ENABLED or DISABLED (paused)';
COMMENT ON COLUMN webserver_domain_dns_record.synced_at IS 'Instant this snapshot row was read from the provider';

CREATE INDEX IF NOT EXISTS idx_webserver_domain_dns_record_zone
    ON webserver_domain_dns_record (tenant_id, root_domain_id, synced_at DESC, id DESC)
    WHERE deleted_at IS NULL;

CREATE INDEX IF NOT EXISTS idx_webserver_domain_dns_record_domain
    ON webserver_domain_dns_record (tenant_id, domain_id)
    WHERE deleted_at IS NULL;

-- Domain ownership verification files for one root domain. Every platform that
-- grants a domain-scoped capability (WeChat MP / mini program JS 安全域名与业务
-- 域名、支付宝/抖音小程序、Google Search Console、Apple Associated Domains、
-- Bing 站点验证) proves ownership by fetching a file it issued from the domain
-- root. The operator uploads that file verbatim and the edge data plane serves
-- it for the root domain's hostname and every registered subdomain under it.
-- A root domain may carry several files at once — one per platform, plus a new
-- one alongside an old one until the operator deletes it — so the uniqueness
-- that matters is (root_domain_id, file_name), not root_domain_id. Content is
-- kept byte-exact: platforms compare bytes.
CREATE TABLE IF NOT EXISTS webserver_domain_verification_file (
    id              BIGINT        NOT NULL,
    uuid            VARCHAR(64)   NOT NULL,
    tenant_id       BIGINT        NOT NULL DEFAULT 0,
    organization_id BIGINT        NOT NULL DEFAULT 0,
    root_domain_id  BIGINT        NOT NULL,
    platform        VARCHAR(32)   NOT NULL,
    file_name       VARCHAR(128)  NOT NULL,
    content         VARCHAR(4096) NOT NULL,
    user_id         BIGINT,
    created_by      BIGINT,
    updated_by      BIGINT,
    created_at      TIMESTAMPTZ   NOT NULL DEFAULT NOW(),
    updated_at      TIMESTAMPTZ   NOT NULL DEFAULT NOW(),
    version         BIGINT        NOT NULL DEFAULT 1,
    deleted_at      TIMESTAMPTZ,
    PRIMARY KEY (id),
    CONSTRAINT uk_webserver_domain_verification_file_uuid UNIQUE (uuid),
    CONSTRAINT uk_webserver_domain_verification_file_name UNIQUE (root_domain_id, file_name),
    CONSTRAINT fk_webserver_domain_verification_file_root
        FOREIGN KEY (root_domain_id) REFERENCES webserver_root_domain(id),
    CONSTRAINT chk_webserver_domain_verification_file_platform CHECK (platform IN (
        'WECHAT_OFFICIAL_ACCOUNT', 'WECHAT_MINI_PROGRAM', 'ALIPAY',
        'BYTEDANCE', 'APPLE', 'GOOGLE', 'CUSTOM'
    )),
    -- Single-segment ASCII, one of the three extensions domain verification
    -- actually uses: .txt (WeChat, Apple), .html (Google), .xml (Bing).
    CONSTRAINT chk_webserver_domain_verification_file_name CHECK (
        file_name ~ '^[A-Za-z0-9][A-Za-z0-9._-]*\.(txt|html|xml)$'
    ),
    CONSTRAINT chk_webserver_domain_verification_file_content CHECK (content <> '')
);

COMMENT ON TABLE webserver_domain_verification_file IS 'Domain ownership verification file; a root domain may register several (one per platform), served verbatim per request hostname';
COMMENT ON COLUMN webserver_domain_verification_file.platform IS 'Issuing platform: WECHAT_OFFICIAL_ACCOUNT / WECHAT_MINI_PROGRAM / ALIPAY / BYTEDANCE / APPLE / GOOGLE / CUSTOM';
COMMENT ON COLUMN webserver_domain_verification_file.file_name IS 'Platform-issued file name (MP_verify_xxx.txt, googleXXX.html, …), served by exact name without case folding';
COMMENT ON COLUMN webserver_domain_verification_file.content IS 'Verification file bytes, stored and returned verbatim';
COMMENT ON COLUMN webserver_domain_verification_file.user_id IS 'Owning user; NULL means tenant-level, same semantics as webserver_domain.user_id';

CREATE INDEX IF NOT EXISTS idx_webserver_domain_verification_file_tenant
    ON webserver_domain_verification_file (tenant_id, root_domain_id)
    WHERE deleted_at IS NULL;

CREATE TABLE IF NOT EXISTS webserver_site_binding (
    id                BIGINT        NOT NULL,
    uuid              VARCHAR(64)   NOT NULL,
    tenant_id         BIGINT        NOT NULL,
    organization_id   BIGINT        NOT NULL DEFAULT 0,
    site_id           BIGINT        NOT NULL,
    domain_id         BIGINT        NOT NULL,
    environment       VARCHAR(16)   NOT NULL DEFAULT 'production',
    path_prefix       VARCHAR(4096) NOT NULL DEFAULT '/',
    action_type       VARCHAR(16)   NOT NULL DEFAULT 'SERVE',
    is_primary        BOOLEAN       NOT NULL DEFAULT false,
    redirect_scheme   VARCHAR(8),
    redirect_hostname VARCHAR(253),
    redirect_path_prefix VARCHAR(4096),
    redirect_status_code INTEGER,
    preserve_path     BOOLEAN       NOT NULL DEFAULT true,
    preserve_query    BOOLEAN       NOT NULL DEFAULT true,
    status            VARCHAR(16)   NOT NULL DEFAULT 'PENDING',
    activated_at      TIMESTAMPTZ,
    created_at        TIMESTAMPTZ   NOT NULL,
    updated_at        TIMESTAMPTZ   NOT NULL,
    version           BIGINT        NOT NULL DEFAULT 0,
    deleted_at        TIMESTAMPTZ,
    PRIMARY KEY (id),
    CONSTRAINT uk_webserver_site_binding_uuid UNIQUE (uuid),
    CONSTRAINT uk_webserver_site_binding_tenant_id UNIQUE (tenant_id, id),
    CONSTRAINT fk_webserver_site_binding_site FOREIGN KEY (tenant_id, site_id)
        REFERENCES webserver_site(tenant_id, id),
    CONSTRAINT fk_webserver_site_binding_domain FOREIGN KEY (tenant_id, domain_id)
        REFERENCES webserver_domain(tenant_id, id),
    CONSTRAINT chk_webserver_site_binding_environment CHECK (environment IN ('development', 'test', 'staging', 'production')),
    CONSTRAINT chk_webserver_site_binding_action CHECK (action_type IN ('SERVE', 'REDIRECT')),
    CONSTRAINT chk_webserver_site_binding_status CHECK (status IN ('PENDING', 'ACTIVE', 'PAUSED', 'FAILED', 'ARCHIVED')),
    CONSTRAINT chk_webserver_site_binding_redirect_status CHECK (redirect_status_code IS NULL OR redirect_status_code IN (301, 302, 307, 308)),
    CONSTRAINT chk_webserver_site_binding_redirect CHECK (
        (action_type = 'SERVE' AND redirect_scheme IS NULL AND redirect_hostname IS NULL AND redirect_path_prefix IS NULL AND redirect_status_code IS NULL)
        OR (action_type = 'REDIRECT' AND redirect_status_code IS NOT NULL)
    )
);

CREATE UNIQUE INDEX IF NOT EXISTS uk_webserver_site_binding_active_route
    ON webserver_site_binding (domain_id, environment, path_prefix)
    WHERE status IN ('PENDING', 'ACTIVE', 'PAUSED') AND deleted_at IS NULL;

CREATE UNIQUE INDEX IF NOT EXISTS uk_webserver_site_binding_primary
    ON webserver_site_binding (site_id, environment)
    WHERE is_primary = true AND status = 'ACTIVE' AND deleted_at IS NULL;

CREATE INDEX IF NOT EXISTS idx_webserver_site_binding_site_status
    ON webserver_site_binding (tenant_id, site_id, environment, status, updated_at DESC, id DESC)
    WHERE deleted_at IS NULL;

CREATE INDEX IF NOT EXISTS idx_webserver_site_binding_domain_status
    ON webserver_site_binding (tenant_id, domain_id, environment, status, updated_at DESC, id DESC)
    WHERE deleted_at IS NULL;

CREATE TABLE IF NOT EXISTS webserver_tls_policy (
    id                  BIGINT       NOT NULL,
    uuid                VARCHAR(64)  NOT NULL,
    tenant_id           BIGINT       NOT NULL,
    site_binding_id     BIGINT       NOT NULL,
    certificate_source  VARCHAR(16)  NOT NULL DEFAULT 'MANAGED',
    challenge_method    VARCHAR(16)  NOT NULL DEFAULT 'AUTO',
    minimum_tls_version VARCHAR(8)   NOT NULL DEFAULT 'TLS1.2',
    maximum_tls_version VARCHAR(8)   NOT NULL DEFAULT 'TLS1.3',
    alpn_json           JSONB        NOT NULL DEFAULT '["h2","http/1.1"]',
    auto_renew          BOOLEAN      NOT NULL DEFAULT true,
    renew_before_days   INTEGER      NOT NULL DEFAULT 30,
    status              VARCHAR(16)  NOT NULL DEFAULT 'ACTIVE',
    created_at          TIMESTAMPTZ  NOT NULL,
    updated_at          TIMESTAMPTZ  NOT NULL,
    version             BIGINT       NOT NULL DEFAULT 0,
    deleted_at          TIMESTAMPTZ,
    PRIMARY KEY (id),
    CONSTRAINT uk_webserver_tls_policy_uuid UNIQUE (uuid),
    CONSTRAINT fk_webserver_tls_policy_binding FOREIGN KEY (tenant_id, site_binding_id)
        REFERENCES webserver_site_binding(tenant_id, id),
    CONSTRAINT chk_webserver_tls_policy_source CHECK (certificate_source IN ('MANAGED', 'CUSTOM', 'EXTERNAL')),
    CONSTRAINT chk_webserver_tls_policy_challenge CHECK (challenge_method IN ('AUTO', 'HTTP_01', 'DNS_01')),
    CONSTRAINT chk_webserver_tls_policy_versions CHECK (
        minimum_tls_version IN ('TLS1.2', 'TLS1.3')
        AND maximum_tls_version IN ('TLS1.2', 'TLS1.3')
        AND minimum_tls_version <= maximum_tls_version
    ),
    CONSTRAINT chk_webserver_tls_policy_renewal CHECK (renew_before_days BETWEEN 14 AND 90),
    CONSTRAINT chk_webserver_tls_policy_status CHECK (status IN ('ACTIVE', 'PAUSED', 'ARCHIVED'))
);

CREATE UNIQUE INDEX IF NOT EXISTS uk_webserver_tls_policy_active_binding
    ON webserver_tls_policy (site_binding_id)
    WHERE status = 'ACTIVE' AND deleted_at IS NULL;

