    CONSTRAINT chk_webserver_server_tenant_scope_hash
        CHECK (tenant_scope_hash ~ '^[0-9a-f]{64}$')
);

COMMENT ON TABLE webserver_server IS 'Web edge server registry';
COMMENT ON COLUMN webserver_server.status IS 'Status: 0=offline, 1=online, 2=deploying, 3=error, 4=maintenance';

CREATE INDEX IF NOT EXISTS idx_webserver_server_tenant_status
    ON webserver_server (tenant_id, status, updated_at DESC);

-- List-query hardening: Web Node keyset listing orders by (updated_at DESC,
-- id DESC) without a status predicate; this index covers the keyset seek.
CREATE INDEX IF NOT EXISTS idx_webserver_server_tenant_updated
    ON webserver_server (tenant_id, updated_at DESC);

