    CONSTRAINT fk_webserver_certificate_node_state_server FOREIGN KEY (tenant_id, server_id)
        REFERENCES webserver_server(tenant_id, id),
    CONSTRAINT fk_webserver_certificate_node_state_certificate FOREIGN KEY (tenant_id, certificate_id)
        REFERENCES webserver_certificate(tenant_id, id),
    CONSTRAINT fk_webserver_certificate_node_state_version FOREIGN KEY (certificate_id, certificate_version_id)
        REFERENCES webserver_certificate_version(certificate_id, id),
    CONSTRAINT chk_webserver_certificate_node_state_phase CHECK (
        state IN ('STAGED', 'ACTIVE', 'SERVED', 'FAILED')
    ),
    CONSTRAINT chk_webserver_certificate_node_state_fingerprint CHECK (
        fingerprint_sha256 ~ '^[0-9a-f]{64}$'
    ),
    CONSTRAINT chk_webserver_certificate_node_state_sync_version CHECK (
        sync_version ~ '^sv1:[0-9a-f]{64}$'
    ),
    CONSTRAINT chk_webserver_certificate_node_state_failure_code CHECK (
        failure_code IS NULL OR failure_code ~ '^[A-Z0-9][A-Z0-9_.-]{0,63}$'
    )
);

CREATE INDEX IF NOT EXISTS idx_webserver_certificate_node_state_version
    ON webserver_certificate_node_state (tenant_id, certificate_version_id, state, server_id);

CREATE INDEX IF NOT EXISTS idx_webserver_certificate_node_state_server
    ON webserver_certificate_node_state (tenant_id, server_id, state, observed_at DESC);

CREATE TABLE IF NOT EXISTS webserver_runtime_assignment (
    id                  BIGINT        NOT NULL,
    uuid                VARCHAR(64)   NOT NULL,
    tenant_id           BIGINT        NOT NULL,
    server_id           BIGINT        NOT NULL,
    environment         VARCHAR(32)   NOT NULL,
    generation          BIGINT        NOT NULL,
    snapshot_uuid       VARCHAR(128)  NOT NULL,
    snapshot_sha256     VARCHAR(64)   NOT NULL,
    runtime_set         JSONB         NOT NULL,
    runtime_set_bytes   BIGINT        NOT NULL,
    assigned_by_subject VARCHAR(128)  NOT NULL,
    created_at          TIMESTAMPTZ   NOT NULL,
    updated_at          TIMESTAMPTZ   NOT NULL,
    version             BIGINT        NOT NULL DEFAULT 0,
    PRIMARY KEY (id),
    CONSTRAINT uk_webserver_runtime_assignment_uuid UNIQUE (uuid),
    CONSTRAINT uk_webserver_runtime_assignment_tenant_id
        UNIQUE (tenant_id, id, server_id),
    CONSTRAINT uk_webserver_runtime_assignment_generation
        UNIQUE (tenant_id, server_id, environment, generation),
    CONSTRAINT uk_webserver_runtime_assignment_snapshot UNIQUE (snapshot_uuid),
    CONSTRAINT fk_webserver_runtime_assignment_server
        FOREIGN KEY (tenant_id, server_id) REFERENCES webserver_server (tenant_id, id),
    CONSTRAINT chk_webserver_runtime_assignment_environment
        CHECK (environment IN ('development', 'test', 'staging', 'production')),
    CONSTRAINT chk_webserver_runtime_assignment_generation
        CHECK (generation BETWEEN 1 AND 9007199254740991),
    CONSTRAINT chk_webserver_runtime_assignment_snapshot_sha256
        CHECK (snapshot_sha256 ~ '^[0-9a-f]{64}$'),
    CONSTRAINT chk_webserver_runtime_assignment_runtime_set
        CHECK (jsonb_typeof(runtime_set) = 'object'),
    CONSTRAINT chk_webserver_runtime_assignment_runtime_set_bytes
        CHECK (runtime_set_bytes BETWEEN 1 AND 67108864)
);

COMMENT ON TABLE webserver_runtime_assignment IS
    'Immutable Website runtime-set assignment delivered to one Web Node environment';

CREATE INDEX IF NOT EXISTS idx_webserver_runtime_assignment_current
    ON webserver_runtime_assignment (tenant_id, server_id, environment, generation DESC);

CREATE TABLE IF NOT EXISTS webserver_runtime_observation (
    id              BIGINT        NOT NULL,
    uuid            VARCHAR(64)   NOT NULL,
    tenant_id       BIGINT        NOT NULL,
    assignment_id   BIGINT        NOT NULL,
    server_id       BIGINT        NOT NULL,
    state           VARCHAR(16)   NOT NULL,
    node_version    VARCHAR(64),
    reason_code     VARCHAR(64),
    detail          VARCHAR(512),
    observed_at     TIMESTAMPTZ   NOT NULL,
    created_at      TIMESTAMPTZ   NOT NULL,
    updated_at      TIMESTAMPTZ   NOT NULL,
    version         BIGINT        NOT NULL DEFAULT 0,
    PRIMARY KEY (id),
    CONSTRAINT uk_webserver_runtime_observation_uuid UNIQUE (uuid),
    CONSTRAINT uk_webserver_runtime_observation_state
        UNIQUE (tenant_id, assignment_id, state),
    CONSTRAINT fk_webserver_runtime_observation_assignment
        FOREIGN KEY (tenant_id, assignment_id, server_id)
        REFERENCES webserver_runtime_assignment (tenant_id, id, server_id),
    CONSTRAINT chk_webserver_runtime_observation_state
        CHECK (state IN ('RECEIVED', 'VALIDATED', 'STAGED', 'ACTIVE', 'REJECTED')),
    CONSTRAINT chk_webserver_runtime_observation_reason
        CHECK (
            (state = 'REJECTED' AND reason_code IS NOT NULL)
            OR (state <> 'REJECTED' AND reason_code IS NULL AND detail IS NULL)
        )
);

COMMENT ON TABLE webserver_runtime_observation IS
    'Append-only Web Node activation observations for an immutable runtime assignment';

CREATE INDEX IF NOT EXISTS idx_webserver_runtime_observation_assignment
    ON webserver_runtime_observation (tenant_id, assignment_id, id DESC);

CREATE INDEX IF NOT EXISTS idx_webserver_runtime_observation_node_time
    ON webserver_runtime_observation (tenant_id, server_id, observed_at DESC);

